const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;
const candidateName = webhookData.candidateName || webhookData.name || 'Ứng viên';
const candidateEmail = webhookData.candidateEmail || webhookData.email || 'candidate@example.com';
const jobTitle = webhookData.jobTitle || 'Chưa rõ chức danh';
const jobDescription = webhookData.jobDescription || '';
const jobRequirements = webhookData.jobRequirements || '';
const cvText = ($json.text || '').trim();

const promptText = `Bạn là Giám đốc Tuyển dụng Nhân sự cao cấp và Trợ lý AI Đánh giá CV (Enterprise AI Recruitment Specialist).
Nhiệm vụ của bạn là phân tích sâu hồ sơ ứng viên so với bản mô tả công việc (JD) và các yêu cầu tuyển dụng được cung cấp dưới đây.

=== BẢN MÔ TẢ CÔNG VIỆC ===
- Vị trí: ${jobTitle}
- Mô tả công việc:
${jobDescription}
- Yêu cầu ứng viên:
${jobRequirements}

=== NỘI DUNG CV CỦA ỨNG VIÊN ===
${cvText}

=== HƯỚNG DẪN ĐÁNH GIÁ ĐA TIÊU CHÍ ===
1. matchScore: Điểm phù hợp tổng thể từ 0 đến 100 (số nguyên hoặc số thực).
2. techScore: Điểm chuyên môn kỹ thuật từ 0 đến 100 (đánh giá mức độ khớp kỹ năng công nghệ cốt lõi).
3. experienceYears: Số năm kinh nghiệm làm việc ước tính liên quan đến vị trí (số nguyên >= 0).
4. summary: Nhận xét sắc sảo bằng tiếng Việt (2-4 câu), nêu bật điểm mạnh nhất và điểm cần cải thiện.
5. parsedSkillsJson: Mảng chuỗi các kỹ năng cứng/công nghệ/công cụ bóc tách từ CV.
6. softSkills: Mảng chuỗi các kỹ năng mềm/kỹ năng làm việc nhóm bóc tách từ CV.
7. recommendation: Một trong ba giá trị sau dựa trên matchScore:
   - "FAST_TRACK_INTERVIEW" (nếu matchScore >= 80)
   - "MANUAL_REVIEW" (nếu 50 <= matchScore < 80)
   - "TALENT_POOL_ARCHIVE" (nếu matchScore < 50)

BẮT BUỘC: Bạn CHỈ ĐƯỢC PHÉP trả về DUY NHẤT một chuỗi JSON thuần (STRICT JSON), KHÔNG kèm bất kỳ định dạng markdown nào khác ngoài cấu trúc JSON sau:
{
  "matchScore": 85,
  "techScore": 90,
  "experienceYears": 3,
  "summary": "Nhận xét tiếng Việt...",
  "parsedSkillsJson": ["Kỹ năng 1", "Kỹ năng 2"],
  "softSkills": ["Giao tiếp", "Làm việc nhóm"],
  "recommendation": "FAST_TRACK_INTERVIEW"
}`;

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    promptText
  }
}];

const promptNodeData = $('Build Detailed Gemini Prompt').first().json;
const candidateId = promptNodeData.candidateId;
const candidateName = promptNodeData.candidateName;
const candidateEmail = promptNodeData.candidateEmail;
const jobTitle = promptNodeData.jobTitle;
const responseJson = $json;

// Trích xuất text từ phản hồi Gemini
const rawText = responseJson.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let cleanedText = rawText.trim();
if (cleanedText.startsWith('```json')) {
  cleanedText = cleanedText.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleanedText.startsWith('```')) {
  cleanedText = cleanedText.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let parsed;
try {
  parsed = JSON.parse(cleanedText);
} catch (e) {
  parsed = {
    matchScore: 0,
    techScore: 0,
    experienceYears: 0,
    summary: "Lỗi phân tích cú pháp từ phản hồi AI: " + e.message,
    parsedSkillsJson: [],
    softSkills: [],
    recommendation: "TALENT_POOL_ARCHIVE"
  };
}

let matchScore = typeof parsed.matchScore === 'number' ? parsed.matchScore : (parseFloat(parsed.matchScore) || 0);
if (matchScore > 100) matchScore = 100;
if (matchScore < 0) matchScore = 0;

let techScore = typeof parsed.techScore === 'number' ? parsed.techScore : (parseFloat(parsed.techScore) || matchScore);
let experienceYears = typeof parsed.experienceYears === 'number' ? Math.round(parsed.experienceYears) : (parseInt(parsed.experienceYears, 10) || 0);

const summary = typeof parsed.summary === 'string' && parsed.summary.trim().length > 0
  ? parsed.summary.trim()
  : "Đã hoàn thành đánh giá hồ sơ ứng viên.";

const parsedSkillsJson = Array.isArray(parsed.parsedSkillsJson) ? parsed.parsedSkillsJson : [];
const softSkills = Array.isArray(parsed.softSkills) ? parsed.softSkills : [];

let recommendation = parsed.recommendation || (matchScore >= 80 ? 'FAST_TRACK_INTERVIEW' : (matchScore >= 50 ? 'MANUAL_REVIEW' : 'TALENT_POOL_ARCHIVE'));

return [{
  json: {
    candidateId,
    name: candidateName,
    email: candidateEmail,
    jobTitle,
    matchScore,
    techScore,
    experienceYears,
    summary,
    parsedSkillsJson,
    softSkills,
    recommendation
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên tiềm năng';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const techScore = candidate.techScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';
const summary = candidate.summary || '';

// Đề xuất ngày phỏng vấn sau 3 ngày làm việc lúc 09:30 AM
const interviewDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000);
interviewDate.setHours(9, 30, 0, 0);
const formattedDate = interviewDate.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});
const formattedTime = '09:30 - 10:30 (Giờ Việt Nam)';

const randomRoomId = Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 5);
const googleMeetUrl = `https://meet.google.com/${randomRoomId}`;

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #10b981 0%, #059669 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 24px; font-weight: 800;">THƯ MỜI PHỎNG VẤN TRỰC TUYẾN</h1>
    <p style="margin: 8px 0 0 0; font-size: 14px; opacity: 0.9;">AI Recruitment Agent • Fast-Track Interview</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Chúc mừng bạn! Hồ sơ ứng tuyển của bạn cho vị trí <strong>${jobTitle}</strong> đã được hệ thống AI đánh giá rất cao với điểm tương thích ấn tượng <strong style="color: #10b981; font-size: 16px;">${matchScore}%</strong> (Điểm kỹ thuật: ${techScore}%).
    </p>
    <div style="background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 12px; padding: 20px; margin: 20px 0;">
      <h3 style="margin: 0 0 10px 0; color: #047857; font-size: 14px;">LỊCH HẸN PHỎNG VẤN TRỰC TUYẾN</h3>
      <p style="margin: 4px 0; font-size: 13px;"><strong>Thời gian:</strong> ${formattedTime}, ${formattedDate}</p>
      <p style="margin: 4px 0; font-size: 13px;"><strong>Đường dẫn Google Meet:</strong> <a href="${googleMeetUrl}" style="color: #059669; font-weight: 700;">${googleMeetUrl}</a></p>
    </div>
    <p style="font-size: 13px; color: #64748b;">Trân trọng,<br><strong>Hội đồng Tuyển dụng & AI Recruitment Agent</strong></p>
  </div>
</div>`;

return [{
  json: {
    action: 'FAST_TRACK_INTERVIEW_SCHEDULED',
    tier: 'TIER_1_EXCELLENT',
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    techScore,
    skills,
    summary,
    interviewDate: formattedDate,
    interviewTime: formattedTime,
    googleMeetUrl,
    emailSubject: `[HR Tech] Thư mời phỏng vấn vị trí ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    alertType: 'HIGH_PRIORITY_CANDIDATE',
    message: `[AI RECRUITMENT] Ứng viên xuất sắc ${data.candidateName} đạt ${data.matchScore}% cho vị trí ${data.jobTitle}. Đã tạo phòng Meet: ${data.googleMeetUrl}`,
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    matchScore: data.matchScore,
    scheduledInterview: `${data.interviewTime}, ${data.interviewDate}`,
    googleMeetUrl: data.googleMeetUrl,
    timestamp: new Date().toISOString()
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';
const summary = candidate.summary || '';

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 22px; font-weight: 800;">THÔNG BÁO XÉT DUYỆT HỒ SƠ</h1>
    <p style="margin: 8px 0 0 0; font-size: 14px; opacity: 0.9;">AI Recruitment Agent • HR Review</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Cảm ơn bạn đã ứng tuyển vị trí <strong>${jobTitle}</strong>. Hồ sơ của bạn đã vượt qua vòng sơ loại tự động với điểm tương thích <strong>${matchScore}%</strong>.
    </p>
    <div style="background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px; padding: 18px; margin: 20px 0;">
      <p style="margin: 0; font-size: 13px; color: #1e40af; line-height: 1.6;">
        Hồ sơ của bạn hiện đang được chuyển tới Trưởng bộ phận chuyên môn xem xét chi tiết các dự án và kinh nghiệm liên quan. Chúng tôi sẽ thông báo kết quả cụ thể trong vòng 2-3 ngày làm việc.
      </p>
    </div>
    <p style="font-size: 13px; color: #64748b;">Trân trọng,<br><strong>Ban Tuyển dụng & AI Recruitment Agent</strong></p>
  </div>
</div>`;

return [{
  json: {
    action: 'MANUAL_HR_REVIEW_QUEUED',
    tier: 'TIER_2_POTENTIAL',
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    summary,
    reviewStatus: 'PENDING_HIRING_MANAGER_REVIEW',
    emailSubject: `[HR Tech] Cập nhật tiến độ hồ sơ ứng tuyển ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    queueType: 'MANUAL_REVIEW_QUEUE',
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    actionRequired: 'Trưởng bộ phận chuyên môn xem xét CV trong 48h',
    queuedAt: new Date().toISOString()
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #475569 0%, #1e293b 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 22px; font-weight: 800;">THƯ CẢM ƠN ỨNG TUYỂN</h1>
    <p style="margin: 8px 0 0 0; font-size: 13px; opacity: 0.85;">AI Recruitment Agent • Talent Pool Retention</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Cảm ơn bạn đã dành thời gian nộp hồ sơ cho vị trí <strong>${jobTitle}</strong>. Dù hiện tại yêu cầu vị trí này chưa thực sự trùng khớp với thế mạnh chuyên môn của bạn, chúng tôi rất trân trọng năng lực và kinh nghiệm của bạn.
    </p>
    <div style="background: #f8fafc; border-left: 4px solid #64748b; border-radius: 6px; padding: 14px; margin: 20px 0;">
      <p style="margin: 0; font-size: 13px; color: #475569; line-height: 1.6;">
        Hồ sơ của bạn đã được chủ động lưu vào <strong>Mạng lưới Nhân tài (Talent Pool)</strong>. Khi có dự án hoặc vị trí mới phù hợp hơn, chúng tôi sẽ ưu tiên liên hệ trực tiếp với bạn.
      </p>
    </div>
    <p style="font-size: 13px; color: #64748b;">Trân trọng,<br><strong>Ban Tuyển dụng & AI Recruitment Agent</strong></p>
  </div>
</div>`;

return [{
  json: {
    action: 'TALENT_POOL_ARCHIVED',
    tier: 'TIER_3_RESERVE',
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    status: 'SAVED_TO_TALENT_POOL',
    emailSubject: `[HR Tech] Thư cảm ơn ứng tuyển vị trí ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    archiveStatus: 'TALENT_POOL_ACTIVE',
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    archivedAt: new Date().toISOString(),
    note: 'Lưu trữ hồ sơ dự phòng, ưu tiên liên hệ khi mở đợt tuyển dụng mới'
  }
}];

const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;

return [{
  json: {
    candidateId,
    matchScore: 0,
    experienceYears: 0,
    summary: "CV trống hoặc không đọc được nội dung văn bản (file PDF dạng ảnh scan hoặc không có chữ).",
    parsedSkillsJson: [],
    errorFlag: 'EMPTY_OR_SCANNED_PDF'
  }
}];
